-- Omgång 7 (2026-11-10): beskrivningar utifrån Viktors info och länkar, borttagna platser och rättade uppgifter.
begin;

-- 1. Nya beskrivningar (13 platser)
update public.places set short_description = 'Thailändsk mat vid vägen mot Glemmingebro', description = 'Asian Corner är en thairestaurang precis vid vägen in mot Glemmingebro. Här lagar man thailändsk mat, och det är ett enkelt och smidigt stopp när hungern slår till under en tur på södra Österlen. Ät på plats eller ta med maten och njut av den vid havet.' where id = 41; -- Asian Corner Glemmingebro
update public.places set short_description = 'Crêperie och café i fransk anda', description = 'Madame Blå i Skåne-Tranås är en crêperie och ett café med franska smaker. Här äter man galetter, de salta bovetepannkakorna från Bretagne, eller väljer bland ett stort utbud av bakverk till kaffet. Maten och fikat lagas från grunden. Ett trevligt stopp på norra Österlen, oavsett om man är sugen på något matigt eller sött.' where id = 109; -- Crêperie & Café Madame Blå
update public.places set short_description = 'Café med surdegspizza i Stärkan i Kivik', description = 'Sally på Kivik är ett café och en restaurang i Handelshuset Stärkan, den vita byggnaden längs Kiviks stora väg. Hit kommer man för surdegspizza, matigare rätter och bakverk till kaffet. Bakom stället står Cattis och Johan Feuk, som också driver Kaffestugan Annorlunda, och de öppnade Sally våren 2025. I samma hus finns butiken Reunion med kläder och inredning, så det är lätt att kombinera en fika med lite shopping. Kolla gärna öppettiderna innan, eftersom caféet inte har öppet alla dagar.' where id = 116; -- Sally på Kivik
update public.places set short_description = 'Färgstark design och konst i Hammenhög', description = 'Tropical Scandinavia är en butik och designstudio i Hammenhög som drivs av paret Johanna och Emil Stark. De gör alla mönster själva, och mönstren blir sedan till mattor, plädar, kuddar, smycken, tryck och konst. Stilen är färgglad och blandar nordiskt med intryck från resor och andra kulturer. Ett återkommande motiv är en tiger med sex ögon. Butiken är värd ett besök för den som letar efter något annorlunda till hemmet eller en present. Allt finns också i deras webbutik.' where id = 174; -- Tropical Scandinavia
update public.places set short_description = 'Konstgalleri i en gammal lada i Kivik', description = 'Galleri Handell är ett litet konstgalleri på Kiviks Stora väg i Kivik. Sune och Gunilla har gjort om den gamla ladan på Skogsdalagården till ett ljust utställningsrum, och sedan påsken 2023 visar de konst här. Utställningarna byts ofta, ungefär var eller varannan vecka, och pågår från våren till hösten. Här visas måleri, grafik, akvarell, fotografi och keramik av konstnärer från hela Sverige. Konst finns också att köpa i galleriets webbutik året runt. Kolla Instagram för aktuella utställningar och öppettider.' where id = 180; -- Galleri Handell
update public.places set short_description = 'Konsthall med fokus på samtidskonst', description = 'Brösarps Konsthall har visat konst sedan 2006 och är en mötesplats för konst och kultur på norra Österlen. Konsthallen samarbetar med Galleri Leger och lägger särskild vikt vid unga konstnärer som arbetar i dag, men här visas också många andra sorters konst. Utställningarna byts under året, så det finns ofta något nytt att se. Ett besök passar bra ihop med en promenad i Brösarps backar. Kolla gärna konsthallens Instagram för aktuell utställning och öppettider.' where id = 181; -- Brösarps Konsthall 
update public.places set short_description = 'Keramikverkstad och butik bland äppelträden i Kivik', description = 'Kajsa H Konst & Keramik är en keramikverkstad med butik i Kivik, mellan äppelodlingarna och havet. Följ skyltarna mot Kiviks Musteri så hittar du dit. All keramik är handgjord, så varje föremål blir lite unikt i form och glasyr. I butiken finns både hela serviser och mer udda och experimentella saker, och det går ofta att se arbetet i verkstaden. Serviserna tål både diskmaskin och mikrovågsugn. Det finns också en webbutik. Hör gärna av dig innan besöket för att höra när det är öppet.' where id = 232; -- Kajsa H Konst & Keramik 
update public.places set short_description = 'Litet gårdshotell med rum och glamping', description = 'Rörums Gårdshotell är ett litet gårdshotell i Rörum, med nära till både havet, stranden och skogen. Hotellet har tolv rum som alla är olika, både dubbelrum och rum för tre. Flera rum har kontinentalsängar och några har en egen uteplats. Den som vill bo närmare naturen kan välja glamping med utsikt över hagarna. Hund får följa med i vissa rum mot en avgift. Från Rörum är det nära till Knäbäckshusens strand och Stenshuvuds nationalpark. Boka gärna i förväg.' where id = 251; -- Rörums Gårdshotell
update public.places set short_description = 'Bed and breakfast med trädgård nära Kivik', description = 'Mellby 11 är ett familjedrivet bed and breakfast strax utanför Kivik. Kajsa driver stället och möter gästerna varje dag. Här finns fyra rum, några med egen dusch och toalett, och frukosten serveras som buffé, gärna ute i den lummiga trädgården. Till gården hör också ett litet konstgalleri. Det är nära till Kivik, Simrishamn, Stenshuvud och havet, och bussen stannar precis utanför. Säsongen sträcker sig från april till sent på hösten, och man bor minst två nätter.' where id = 261; -- Mellby 11 Bed & Breakfast Österlen
update public.places set short_description = 'Gammaldags lanthandel med fem generationers historia', description = 'Leif Handlare i Glemmingebro är en riktig lanthandel, och familjen har drivit handel här i fem generationer. Här står ostarna i disken och skärs upp som man vill ha dem, och det finns rökt korv, fläsk, nybakade frallor och nymalet kaffe. Godiset säljs i strut som förr, och på hyllorna står tvål, ljus och lokala varor bland den gamla inredningen. Ta gärna med en kopp kaffe och en fralla för vägen. En lanthandel som visar hur det var att handla förr.' where id = 263; -- Leif Handlare
update public.places set short_description = 'Blomsterbutik med buketter och arrangemang', description = 'Trolldruvan flower cottage gör buketter och blomsterarrangemang med mycket kreativitet. Butiken har flyttat till en gård längs Österleden, nära Köpingebro, där de nu bygger upp sin verksamhet. Kolla Facebook och Instagram för öppettider innan ni åker.' where id = 291; -- Trolldruvan flower cottage
update public.places set short_description = 'Prylmarknad och loppis i Hammenhög', description = 'Allt i Allo är en prylmarknad och loppis i Allt i Allo Hallen på Herrestadsvägen i Hammenhög. Här finns begagnade prylar, möbler och mycket annat till låga priser, och det ordnas också bakluckeloppis. Det är ett roligt ställe att leta fynd på, både för den som letar efter något särskilt och för den som bara vill gå runt och titta. Loppisen har öppet på lördagar under säsongen. Företaget hjälper också till med bland annat städning och tömning av dödsbon.' where id = 311; -- Allt I Allo
update public.places set short_description = 'Sportbutik i Simrishamn med brett utbud', description = 'Team Sportia i Simrishamn är en sportbutik med kläder, skor och utrustning för både barn och vuxna. Team Sportia är en kedja av fristående handlare, så varje butik väljer sitt eget sortiment efter vad som efterfrågas lokalt. Här hittar man saker för löpning, cykel, fotboll, padel, friluftsliv och mycket annat. Det gör butiken till ett bra ställe att komplettera utrustningen inför en vandring, en cykeltur eller en dag på stranden. Kolla gärna öppettiderna innan.' where id = 317; -- Team Sportia I Simrishamn

